def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    yesterday_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if float(opp.get('budget', 0)) >= DAILY_SALARY * 4:
                rich_opp += 1
            if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 0)) <= 4:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    yesterday_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    emergency = no_water >= 2 or hp <= 3
    pressured = no_water >= 1 or hp <= 6

    if emergency:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 3.0)
        if tight_supply:
            bid = max(bid, 1.02 * highest_prev + 2.0)
        return float(min(budget, bid))

    if loose_supply and not pressured:
        bid = max(6.0, min(18.0, avg_prev * 0.28 + 4.0))
        return float(min(budget, bid))

    if tight_supply:
        if highest_prev >= 95:
            if hp >= 7 and no_water == 0:
                bid = 12.0
            else:
                bid = min(0.88 * DAILY_SALARY, highest_prev * 0.72)
        else:
            bid = max(34.0, highest_prev + 2.5)
            if urgent_opp >= 2:
                bid += 4.0
        return float(min(budget, bid))

    bid = 22.0
    if pressured:
        bid = max(bid, 42.0)
    if highest_prev > 0:
        if highest_prev >= 90:
            bid = max(bid, 24.0 if not pressured else 48.0)
        elif highest_prev >= 65:
            bid = max(bid, highest_prev * 0.7)
        else:
            bid = max(bid, highest_prev + 1.5)

    if rich_opp >= 2 and not pressured:
        bid *= 0.9
    if day >= 8 and hp >= 7 and no_water == 0:
        bid *= 0.9

    reserve_floor = DAILY_SALARY * 0.35
    if budget < reserve_floor and not pressured:
        bid = min(bid, 18.0)

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Get yesterday's bids from previous_trace
    prev_bids = []
    for opp in alive.values():
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Determine urgency
    urgent = my_status['hp'] <= 3 or my_status['no_water_days'] >= 2

    supply = day_context['supply']

    if urgent:
        # Desperate: bid high to guarantee water
        bid = min(my_status['budget'], DAILY_SALARY * 0.9)
        return bid

    # Not urgent: try to save budget
    if prev_bids:
        avg_prev = sum(prev_bids) / len(prev_bids)
        # Adjust based on supply pressure
        if supply < 20:
            target = max(avg_prev + 5, DAILY_SALARY * 0.6)
        else:
            target = avg_prev + 2
        # Never exceed a safe cap to avoid waste
        cap = DAILY_SALARY * 0.7
        bid = min(target, cap)
    else:
        # No previous data: bid moderate
        bid = DAILY_SALARY * 0.45

    # Ensure we don't exceed budget
    bid = min(bid, my_status['budget'])
    return max(1, bid)
